function checkEmail(email) {
  // Regular expression to match basic email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

function handleSubmit(event) {
  const emailInput = document.getElementById("email");
  const passwordInput = document.getElementById("password");

  // Validate email and password
  const isValid = checkEmail(emailInput.value) && 
    passwordInput.value.length > 8;

  // Prevent form from submitting if invalid
  if (!isValid) {
    alert("Please provide a valid email and a password with at least 8 characters.");
    event.preventDefault(); // Prevents page reload
  }
}
```

